import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { toggleFeatureFlagAction } from "@/actions/flags/toggle-flag";
import { FEATURE_FLAG_DEFINITIONS } from "@/config/feature-flags";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import type { FeatureFlagKey } from "@/types/feature-flag";
import { loadTenantContext } from "../../_lib/tenant-context";
import { FlagToggleList, type FlagRow } from "./flag-toggle-list";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Feature flags",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "org:manage_flags", {
    kind: "organization",
    orgId: org.id,
  });
  if (!allowed) {
    notFound();
  }

  const context = buildFlagContext(actor, org);
  const overrides = new Set(org.settings.enabledFlagOverrides);

  const rows: readonly FlagRow[] = Object.values(FEATURE_FLAG_DEFINITIONS).map(
    (definition) => ({
      key: definition.key,
      label: definition.label,
      description: definition.description,
      strategy: describeStrategy(definition.strategy.kind),
      overridable: definition.overridable,
      overridden: overrides.has(definition.key),
      enabled: isEnabled(definition.key, context),
    }),
  );

  async function toggle(flag: FeatureFlagKey, enabled: boolean): Promise<void> {
    "use server";
    await toggleFeatureFlagAction({ orgId: org.id, flag, enabled });
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-xl font-semibold tracking-tight">Feature flags</h1>
        <p className="mt-1 text-sm text-slate-600">
          Flags gated on your plan turn on automatically. Overridable ones can be
          switched here for {org.name} only.
        </p>
      </header>

      <FlagToggleList rows={rows} onToggle={toggle} />
    </div>
  );
}

function describeStrategy(kind: string): string {
  switch (kind) {
    case "on":
      return "Always on";
    case "off":
      return "Off by default";
    case "plan":
      return "Included from a certain plan";
    case "role":
      return "Limited by role";
    case "percentage":
      return "Percentage rollout";
    default:
      return kind;
  }
}
"use client";

/**
 * Client-side plumbing for feature flags.
 *
 * The server evaluates every flag once per request with `snapshotFlags()` and
 * serialises the result into `FeatureFlagProvider`. The client therefore reads
 * the snapshot rather than re-deriving anything — but when a key is missing
 * (a snapshot serialised before a newly shipped flag existed) we fall back to
 * `isEnabled()` so there is still exactly one evaluator in the codebase.
 */
import { createContext } from "react";
import { isEnabled } from "@/lib/feature-flags";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Context for a signed-out / pre-hydration reader: free plan, no role. */
export const ANONYMOUS_FLAG_CONTEXT: FlagContext = {
  orgId: null,
  userId: null,
  plan: "free",
  role: null,
};

/** The full evaluation context for a member browsing one organization. */
export function orgFlagContext(org: Organization, actor: Actor): FlagContext {
  return {
    orgId: org.id,
    userId: actor.userId,
    plan: org.plan,
    role: actor.role,
    overrides: org.settings.enabledFlagOverrides,
  };
}

/**
 * Reads one flag out of a server-evaluated snapshot, falling back to a live
 * `isEnabled()` evaluation when the snapshot predates the flag.
 */
export function readFlag(
  snapshot: FeatureFlagSnapshot | null,
  flag: FeatureFlagKey,
  context: FlagContext = ANONYMOUS_FLAG_CONTEXT,
): boolean {
  const evaluated = snapshot?.[flag];
  return typeof evaluated === "boolean"
    ? evaluated
    : isEnabled(flag, context);
}

export const FlagSnapshotContext = createContext<FeatureFlagSnapshot | null>(
  null,
);

